import sys
import os
from fastapi import FastAPI, HTTPException
from fastapi.middleware.cors import CORSMiddleware
from pydantic import BaseModel
from typing import List

# Add research dir to path to import the predictor
sys.path.append(os.path.abspath(os.path.join(os.path.dirname(__file__), '..', 'research')))

try:
    from toxicity_predictor import ToxicityPredictor
except ImportError as e:
    raise RuntimeError(f"Failed to import ToxicityPredictor: {e}")

app = FastAPI(title="ToxLab API", version="1.0.0")

# Enable CORS for the frontend generated by Stitch MCP
app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
)

predictor = ToxicityPredictor()

class AnalysisRequest(BaseModel):
    smiles: str  # Can be a single SMILES or comma-separated

class SimulationRequest(BaseModel):
    smiles: str
    dose: float = 100.0
    duration: float = 48.0

@app.post("/v1/toxicity/compute")
async def compute_toxicity(req: AnalysisRequest):
    if not req.smiles or not req.smiles.strip():
        raise HTTPException(status_code=400, detail="SMILES string cannot be empty")
    
    try:
        # run_workflow handles both single and comma-separated batches automatically
        report = predictor.run_workflow(req.smiles)
        if not report:
            raise HTTPException(status_code=500, detail="Prediction workflow returned empty.")
        return report
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))

@app.post("/v1/toxicity/simulate")
async def simulate_toxicity(req: SimulationRequest):
    if not req.smiles or not req.smiles.strip():
        raise HTTPException(status_code=400, detail="SMILES string cannot be empty")
    
    try:
        # Calls the newly created simulate_run method in ToxicityPredictor
        simulation_results = predictor.simulate_run(
            smiles=req.smiles, 
            dose=req.dose, 
            duration=req.duration
        )
        if "error" in simulation_results:
            raise HTTPException(status_code=500, detail=simulation_results["error"])
        return simulation_results
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))

@app.get("/health")
def health_check():
    return {"status": "ok"}
